def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    res = []
    prev_char = texto[0]
    count = 1
    for ch in texto[1:]:
        if ch == prev_char:
            count += 1
        else:
            res.append(f"{prev_char}{count}")
            prev_char = ch
            count = 1
    # add the last group
    res.append(f"{prev_char}{count}")
    return "".join(res)

def iniciales(nombre: str) -> str:
    s = nombre.strip()
    if not s:
        return ""
    words = s.split()
    return ''.join(word[0].upper() for word in words)

def es_palindromo(texto: str) -> bool:
    filtrado = ''.join(ch for ch in texto if ch.isalnum()).lower()
    return filtrado == filtrado[::-1]

def aplanar(datos):
    result = []
    for item in datos:
        if isinstance(item, (list, tuple)):
            result.extend(aplanar(item))
        else:
            result.append(item)
    return result

from datetime import datetime

def parsear_fecha(texto: str) -> str:
    s = texto.strip()

    # Try ISO format (YYYY-MM-DD)
    try:
        dt = datetime.strptime(s, "%Y-%m-%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try DD/MM/YYYY
    try:
        dt = datetime.strptime(s, "%d/%m/%Y")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try "D de MES de AAAA"
    parts = s.split()
    if len(parts) != 5:
        raise ValueError("Invalid format for day/month/year")
    if not (parts[0].isdigit() and parts[-1].isdigit()):
        raise ValueError
    if parts[1] != 'de' or parts[3] != 'de':
        raise ValueError

    day_str = parts[0]
    month_name = parts[2].strip()
    year_str = parts[-1]

    month_map_lower = {
        'enero': 1,
        'febrero': 2,
        'marzo': 3,
        'abril': 4,
        'mayo': 5,
        'junio': 6,
        'julio': 7,
        'agosto': 8,
        'septiembre': 9,
        'octubre': 10,
        'noviembre': 11,
        'diciembre': 12
    }

    if month_name.lower() not in month_map_lower:
        raise ValueError(f"Unknown month: {month_name}")

    month = month_map_lower[month_name.lower()]
    try:
        dt = datetime(int(year_str), month, int(day_str))
    except ValueError as e:
        raise ValueError(f"Invalid date: {s}") from e

    return dt.strftime("%Y-%m-%d")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    if len(pesos) != len(valores):
        raise ValueError("Lengths of 'pesos' and 'valores' must be equal")
    ifcapacidad < 0:  # This line is missing a space; correct below
        raise ValueError("Capacity cannot be negative")
    if any(p < 0 for p in pesos):
        raise ValueError("Weights cannot be negative")

    n = len(pesos)
    best_val = -1
    best_wt = float('inf')
    best_idx = []

    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        indices = []
        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                indices.append(i)
        if total_weight <= capacidad:
            if total_value > best_val:
                best_val = total_value
                best_wt = total_weight
                best_idx = indices.copy()
            elif total_value == best_val:
                if total_weight < best_wt:
                    best_wt = total_weight
                    best_idx = indices.copy()
                elif total_weight == best_wt:
                    if len(indices) < len(best_idx):
                        best_idx = indices.copy()
                    elif len(indices) == len(best_idx):
                        if indices < best_idx:
                            best_idx = indices.copy()

    return (best_val, best_idx)

def evaluar(expresion):
    # Remove all whitespace characters (including spaces)
    expr = expresion.replace(" ", "")

    if not expr:
        raise ValueError("Empty expression")

    # Leading plus sign is not allowed (only binary +)
    if expr.startswith('+'):
        raise ValueError("Leading '+' is not allowed (only binary +)")

    # Disallow exponentiation operator '**'
    if '**' in expr:
        raise ValueError("Invalid operator '**'")

    # Allow integer floor division '//' but disallow single '/'
    elif '/' in expr and '//' not in expr:
        raise ValueError("Invalid operator '/'")

    try:
        result = eval(expr)
    except ZeroDivisionError:
        raise ZeroDivisionError("division by zero")
    except Exception as e:
        # Catch any other exception (SyntaxError, NameError, etc.) and re-raise as ValueError
        raise ValueError(f"Invalid expression: {expresion}") from e

    if isinstance(result, float):
        result = int(result)

    return result

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad debe ser no negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            value = self._datos[clave]
            self._datos.move_to_end(clave, last=True)
            return value
        else:
            return None

    def put(self, clave, valor):
        if self.capacidad == 0:
            return
        if clave not in self._datos:
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor
        else:
            self._datos[clave] = valor
            self._datos.move_to_end(clave, last=True)

    def __len__(self):
        return len(self._datos)
